'use strict';
const uid=()=>crypto.randomUUID();
const fmt=ms=>{ms=Math.max(0,ms);const s=Math.floor(ms/1000);return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}.${String(Math.floor(ms%1000/10)).padStart(2,'0')}`};
function scoreRace(reg,results){let ok=results.filter(x=>x.status==='OK').sort((a,b)=>a.place-b.place);let position=1;for(let i=0;i<ok.length;){let j=i+1;while(j<ok.length&&ok[j].place===ok[i].place)j++;const points=(position+position+j-i-1)/2;for(let k=i;k<j;k++)ok[k].points=points;position+=j-i;i=j}for(const x of results)if(x.status!=='OK')x.points=['RDG','DPI','SCP','ZFP'].includes(x.status)?x.manualPoints:reg.crews.length+1;return results}
function compare(a,b){if(a.net!==b.net)return a.net-b.net;const aa=a.scores.filter((_,i)=>!a.discard.includes(i)).map(x=>x.points).sort((x,y)=>x-y),bb=b.scores.filter((_,i)=>!b.discard.includes(i)).map(x=>x.points).sort((x,y)=>x-y);for(let i=0;i<Math.min(aa.length,bb.length);i++)if(aa[i]!==bb[i])return aa[i]-bb[i];for(let i=a.scores.length-1;i>=0;i--)if(a.scores[i].points!==b.scores[i].points)return a.scores[i].points-b.scores[i].points;return 0}
function standings(reg){const rows=reg.crews.map(crew=>{const scores=reg.races.map(r=>r.results.find(x=>x.crewId===crew.id)||{points:reg.crews.length+1,status:'DNC'});const count=reg.races.length>=reg.discardAfter?reg.discards:0;const discard=scores.map((x,i)=>({x,i})).filter(a=>a.x.status!=='DNE').sort((a,b)=>b.x.points-a.x.points||a.i-b.i).slice(0,count).map(a=>a.i);return {crew,scores,discard,net:scores.reduce((s,x,i)=>s+(discard.includes(i)?0:x.points),0)}}).sort(compare);rows.forEach((r,i)=>r.rank=i&&compare(r,rows[i-1])===0?rows[i-1].rank:i+1);return rows}
if(typeof module!=='undefined')module.exports={scoreRace,standings,compare,fmt};
